head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > E > onviewchange]<br/>컴포넌트에서 사용자의 조작에 의해 아이템들의 선택 상태가 변경되면 발생합니다.",
    "validation" : [        
        "info.oldInfo.checked 속성값으로 allOption 속성으로 추가된 '전체 선택' 아이템은 allOptionChecked=false 이면 항상 false 값을 갖고, allOptionChecked=true 이면 선택 상태값을 true/false 로 갖습니다.",
        "info.newInfo.checked 속성값으로 allOption 속성으로 추가된 '전체 선택' 아이템은 allOptionChecked=false 이면 항상 false 값을 갖고, allOptionChecked=true 이면 선택 상태값을 true/false 로 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        allOption : true,
        allOptionChecked : con_allOptionChecked.getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onviewchange"]);

    // comp 생성
    $c.gcm.createBasicCheckComboBox(cList, eList);
}



scwin.target1_onviewchange = function (info) {
    for (let i =0; i < 4; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldInfo.checked["+i+"] : " + info.oldInfo[i].checked);
    }

    for (let i =0; i < 4; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("info.newInfo.checked["+i+"] : " + info.newInfo[i].checked);
    }
}
